def _flatten(value):
    """Yield the scalar elements of a (possibly nested) list or tuple."""
    if isinstance(value, (list, tuple)):
        for item in value:
            yield from _flatten(item)
    else:
        yield value


def check_subset_list(list1, list2):
    """Write a function to check if a nested list is a subset of another nested list.

    Both lists are flattened recursively, and the result is True when
    every element of ``list1`` also occurs in ``list2`` (i.e. ``list1``
    is a subset of ``list2``), regardless of order or nesting depth.
    """
    flat_list1 = list(_flatten(list1))
    flat_list2 = list(_flatten(list2))
    try:
        return set(flat_list1) <= set(flat_list2)
    except TypeError:  # unhashable elements
        return all(any(item == other for other in flat_list2) for item in flat_list1)
